<style>
    .finance-live{--ink:#10233f;--muted:#72809a;--line:#e7edf5;--panel:#fff;--bg:#f3f7fc;--blue:#1877f2;--teal:#11a889;--amber:#e8a32c;--red:#df5b69;min-height:calc(100vh - 70px);margin:-25px;background:var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;padding:24px;}
    .finance-wall{max-width:1540px;margin:0 auto}.finance-top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px}.finance-kicker{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--blue);font-weight:800}.finance-title{font-size:clamp(24px,3vw,40px);line-height:1.05;margin:5px 0 7px;font-weight:800;letter-spacing:-.04em}.finance-subtitle{color:var(--muted);font-size:14px;margin:0}.finance-actions{display:flex;align-items:center;gap:10px}.finance-live-pill{display:flex;align-items:center;gap:8px;background:#e9fbf5;color:#12866d;padding:9px 13px;border-radius:999px;font-size:12px;font-weight:800}.finance-live-pill i{width:8px;height:8px;border-radius:50%;background:#16b78e;box-shadow:0 0 0 5px rgba(22,183,142,.14);animation:financePulse 1.8s infinite}.finance-updated{font-size:11px;color:var(--muted);text-align:right}.finance-link{border:1px solid var(--line);background:#fff;border-radius:11px;padding:10px 13px;color:var(--ink);font-size:12px;font-weight:700;text-decoration:none}.finance-kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-bottom:14px}.finance-card{background:var(--panel);border:1px solid var(--line);border-radius:18px;box-shadow:0 12px 30px rgba(30,63,104,.06)}.finance-kpi{padding:18px;position:relative;overflow:hidden}.finance-kpi:after{content:"";position:absolute;width:85px;height:85px;border-radius:50%;right:-25px;top:-27px;background:var(--wash,rgba(24,119,242,.08))}.finance-label{color:var(--muted);font-size:12px;font-weight:700}.finance-value{font-size:clamp(19px,2.2vw,28px);font-weight:850;margin-top:8px;letter-spacing:-.035em}.finance-meta{display:flex;gap:7px;align-items:center;color:var(--muted);font-size:11px;margin-top:8px}.finance-meta strong{color:var(--ink)}.finance-kpi.blue{--wash:rgba(24,119,242,.12)}.finance-kpi.green{--wash:rgba(17,168,137,.13)}.finance-kpi.amber{--wash:rgba(232,163,44,.14)}.finance-kpi.red{--wash:rgba(223,91,105,.13)}.finance-kpi.purple{--wash:rgba(117,92,223,.13)}.finance-kpi.blue .finance-value{color:var(--blue)}.finance-kpi.green .finance-value{color:var(--teal)}.finance-kpi.amber .finance-value{color:#c08317}.finance-kpi.red .finance-value{color:#c84b5b}.finance-kpi.purple .finance-value{color:#7259cb}.finance-section-title{display:flex;align-items:end;justify-content:space-between;margin:24px 0 10px}.finance-section-title h2{font-size:15px;margin:0;font-weight:800}.finance-section-title span{font-size:11px;color:var(--muted)}.finance-systems{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.finance-system{padding:16px;min-height:142px}.finance-system-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.finance-system-name{font-size:14px;font-weight:800}.finance-system-status{font-size:10px;font-weight:800;border-radius:999px;padding:5px 8px;background:#eaf8f2;color:#16836b}.finance-system-status.unavailable{background:#fff4e6;color:#b26d0e}.finance-system-status.error{background:#fff0f2;color:#b64051}.finance-system-amount{font-size:21px;font-weight:850;margin:17px 0 11px}.finance-system-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.finance-system-stats b{display:block;font-size:12px}.finance-system-stats small{display:block;color:var(--muted);font-size:10px;margin-top:2px}.finance-system-foot{margin-top:12px;color:var(--muted);font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.finance-grid{display:grid;grid-template-columns:1.45fr .85fr;gap:14px;margin-top:14px}.finance-bottom{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.finance-panel{padding:18px;min-height:270px}.finance-panel h3{font-size:14px;margin:0 0 4px;font-weight:800}.finance-panel p{font-size:11px;color:var(--muted);margin:0 0 15px}.finance-chart{height:195px;position:relative}.finance-chart svg{width:100%;height:100%;display:block}.finance-axis{display:flex;justify-content:space-between;color:#9aa7ba;font-size:10px;margin-top:3px}.finance-status-row,.finance-service-row{margin:13px 0}.finance-row-head{display:flex;justify-content:space-between;gap:10px;font-size:11px;font-weight:700}.finance-row-head span:last-child{color:var(--muted);font-weight:700}.finance-bar{height:8px;background:#edf2f8;border-radius:99px;overflow:hidden;margin-top:7px}.finance-bar span{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#1877f2,#5aa4ff)}.finance-status-row:nth-child(2) .finance-bar span{background:linear-gradient(90deg,#11a889,#50d4b4)}.finance-status-row:nth-child(3) .finance-bar span{background:linear-gradient(90deg,#df5b69,#f49aa3)}.finance-status-row:nth-child(4) .finance-bar span{background:linear-gradient(90deg,#e8a32c,#f5cd77)}.finance-empty{display:flex;align-items:center;justify-content:center;height:195px;color:var(--muted);font-size:12px}.finance-alert{display:none;align-items:center;gap:8px;background:#fff7e9;color:#a66a0a;border:1px solid #f6dfb4;border-radius:10px;padding:10px 12px;font-size:11px;margin-bottom:14px}.finance-alert.show{display:flex}@keyframes financePulse{50%{opacity:.35;transform:scale(.8)}}
    @media(max-width:1100px){.finance-kpis{grid-template-columns:repeat(3,1fr)}.finance-systems{grid-template-columns:repeat(2,1fr)}.finance-grid{grid-template-columns:1fr}.finance-bottom{grid-template-columns:1fr}}
    @media(max-width:680px){.finance-live{margin:-15px;padding:15px}.finance-top{align-items:flex-start;flex-direction:column}.finance-actions{width:100%;justify-content:space-between}.finance-updated{text-align:left}.finance-kpis{grid-template-columns:repeat(2,1fr);gap:9px}.finance-kpi{padding:14px}.finance-value{font-size:18px}.finance-systems{grid-template-columns:1fr}.finance-panel{padding:15px}.finance-section-title{margin-top:19px}}
</style>
<style>
    /* Match Fees Collection: blue hero, compact bordered KPI cards, and calm
       white panels. This page is intentionally independent of Split Report. */
    .finance-live{background:#f5f8fc;margin:-8px -8px 22px;padding:0 0 24px;min-height:calc(100vh - 70px);color:#172b4d}.finance-wall{max-width:1540px;padding:0 8px}.finance-top{background:linear-gradient(135deg,#123b67 0%,#1769aa 55%,#24a6c8 100%);padding:24px 26px;border-radius:20px;box-shadow:0 14px 34px rgba(22,67,111,.18);position:relative;overflow:hidden;margin-bottom:16px}.finance-top:after{content:"";position:absolute;width:260px;height:260px;border-radius:50%;right:-85px;top:-135px;background:rgba(255,255,255,.12)}.finance-top>div{position:relative;z-index:1}.finance-top .finance-kicker{color:rgba(255,255,255,.72)}.finance-top .finance-title{color:#fff;font-size:clamp(23px,2.7vw,35px);margin-top:6px}.finance-top .finance-subtitle{color:rgba(255,255,255,.8)}.finance-top .finance-link{display:none}.finance-top .finance-live-pill{background:rgba(255,255,255,.15);color:#fff}.finance-top .finance-updated{color:rgba(255,255,255,.72)}.finance-kpis{gap:14px}.finance-card{border-radius:15px;box-shadow:0 5px 18px rgba(24,49,80,.05)}.finance-kpi{border-top:4px solid #1769aa;padding:17px 18px}.finance-kpi.green{border-top-color:#159570}.finance-kpi.amber{border-top-color:#de9b16}.finance-kpi.red{border-top-color:#d9534f}.finance-kpi.purple{display:none}.finance-section-title{margin:20px 0 10px}.finance-section-title h2{font-size:1rem}.finance-system{border-radius:15px}.finance-panel{border-radius:15px}.finance-alert{margin-top:0}
    @media(max-width:680px){.finance-live{margin:0 -2px 18px;padding-bottom:14px}.finance-wall{padding:0 2px}.finance-top{border-radius:15px;padding:20px 17px}.finance-top .finance-title{font-size:1.25rem}.finance-top .finance-actions{width:100%;justify-content:flex-start}.finance-kpis{grid-template-columns:1fr 1fr;gap:9px}.finance-kpi{padding:13px 12px;border-radius:12px}.finance-kpi-value{font-size:1rem}.finance-system,.finance-panel{border-radius:13px}}
</style>

<div class="finance-live" id="financeLive" data-endpoint="{{ url('/admin/remita-finance-live/data') }}">
    <div class="finance-wall">
        <div class="finance-top">
            <div>
                <div class="finance-kicker">Finance command centre</div>
                <h1 class="finance-title">Institutional collection summary</h1>
                <p class="finance-subtitle">A clear, institution-wide view of today’s collections across all four payment systems.</p>
            </div>
            <div class="finance-actions">
                <div><div class="finance-live-pill"><i></i> Live · 10-second sync</div><div class="finance-updated" id="financeUpdated">Connecting…</div></div>
            </div>
        </div>
        <div class="finance-alert" id="financeAlert"><i class="fas fa-triangle-exclamation"></i><span>Some payment systems are temporarily unavailable. Available totals remain live.</span></div>
        <section class="finance-kpis" aria-label="Institution summary">
            <div class="finance-card finance-kpi blue"><div class="finance-label">Base amount collected</div><div class="finance-value" id="kpiPaid">₦0.00</div><div class="finance-meta"><strong id="kpiPaidCount">0</strong> successful payments</div></div>
            <div class="finance-card finance-kpi green"><div class="finance-label">All base payments</div><div class="finance-value" id="kpiGross">₦0.00</div><div class="finance-meta"><strong id="kpiCount">0</strong> payment records</div></div>
            <div class="finance-card finance-kpi amber"><div class="finance-label">Awaiting settlement</div><div class="finance-value" id="kpiPending">₦0.00</div><div class="finance-meta"><strong id="kpiPendingCount">0</strong> pending or processing</div></div>
            <div class="finance-card finance-kpi red"><div class="finance-label">Failed / cancelled</div><div class="finance-value" id="kpiCancelled">₦0.00</div><div class="finance-meta"><strong id="kpiCancelledCount">0</strong> unsuccessful records</div></div>
            <div class="finance-card finance-kpi purple"><div class="finance-label">Latest payment</div><div class="finance-value" id="kpiLatest">—</div><div class="finance-meta">Last recorded activity</div></div>
        </section>

        <div class="finance-section-title"><h2>Collections by system</h2><span>Base amount only · Undergraduate · Postgraduate · SBRS · Institute</span></div>
        <section class="finance-systems" id="financeSystems"></section>

        <div class="finance-grid">
            <section class="finance-card finance-panel"><h3>Collection activity</h3><p>Hourly base amount across all systems today</p><div class="finance-chart" id="financeTrend"></div><div class="finance-axis"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>Now</span></div></section>
            <section class="finance-card finance-panel"><h3>Payment status</h3><p>How today’s payment records are progressing</p><div id="financeStatuses"></div></section>
        </div>
        <div class="finance-bottom">
            <section class="finance-card finance-panel"><h3>Top payment services</h3><p>Highest-value services recorded today</p><div id="financeServices"></div></section>
            <section class="finance-card finance-panel"><h3>Executive readout</h3><p>Operational signals for finance leadership</p><div id="financeReadout"></div></section>
        </div>
    </div>
</div>

<script>
(function(){
    const root=document.getElementById('financeLive'); if(!root)return;
    const endpoint=root.dataset.endpoint, initial=@json($payload ?? []); let inFlight=false;
    const money=new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',minimumFractionDigits:2});
    const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
    const fmt=(v)=>money.format(Number(v||0));
    const shortMoney=(v)=>{const n=Number(v||0);return n>=1000000?'₦'+(n/1000000).toFixed(1)+'m':n>=1000?'₦'+(n/1000).toFixed(0)+'k':fmt(n)};
    const count=(v)=>new Intl.NumberFormat('en-NG').format(Number(v||0));
    const time=(v)=>{if(!v)return '—';const d=new Date(v);return isNaN(d)?'—':d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});};
    function set(id,value){const e=document.getElementById(id);if(e)e.textContent=value;}
    function renderSystems(rows){
        const host=document.getElementById('financeSystems'); host.innerHTML=(rows||[]).map(s=>{const syncing=s.status==='syncing', unavailable=s.status!=='ok'&&!syncing;return `<article class="finance-card finance-system"><div class="finance-system-head"><div class="finance-system-name">${esc(s.label)}</div><span class="finance-system-status ${unavailable?'unavailable':''}">${syncing?'Syncing…':(unavailable?'Unavailable':'Connected')}</span></div><div class="finance-system-amount">${fmt(s.paid_amount||0)}</div><div class="finance-system-stats"><div><b>${count(s.paid_count)}</b><small>Collected</small></div><div><b>${fmt(s.pending_amount||0)}</b><small>Pending</small></div><div><b>${count(s.count)}</b><small>Records</small></div></div><div class="finance-system-foot">${unavailable?esc(s.error||'Source did not respond'):(syncing?'Waiting for first sync…':('Today · latest '+time(s.last_payment_at)))}</div></article>`}).join('');
    }
    function renderBars(id,rows,type){const host=document.getElementById(id);if(!rows||!rows.length){host.innerHTML='<div class="finance-empty">No activity recorded today</div>';return;}const max=Math.max(...rows.map(x=>Number(x.gross_amount||0)),1);host.innerHTML=rows.slice(0,8).map(r=>`<div class="finance-${type}-row"><div class="finance-row-head"><span>${esc(r.status||r.label)}</span><span>${fmt(r.gross_amount)} · ${count(r.payment_count)} records</span></div><div class="finance-bar"><span style="width:${Math.max(2,Math.min(100,Number(r.gross_amount||0)/max*100))}%"></span></div></div>`).join('');}
    function renderTrend(rows){const host=document.getElementById('financeTrend');if(!rows||!rows.length){host.innerHTML='<div class="finance-empty">No collection activity recorded today</div>';return;}const points=rows.slice(-24), max=Math.max(...points.map(x=>Number(x.gross_amount||0)),1),w=760,h=185,p=12;const coords=points.map((x,i)=>[p+(i*(w-p*2)/Math.max(points.length-1,1)),h-p-(Number(x.gross_amount||0)/max*(h-p*2))]);const line=coords.map((q,i)=>(i?'L':'M')+q[0].toFixed(1)+' '+q[1].toFixed(1)).join(' ');const area=line+' L '+coords[coords.length-1][0]+' '+(h-p)+' L '+coords[0][0]+' '+(h-p)+' Z';host.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-label="Hourly collection chart"><defs><linearGradient id="financeGrad" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#1877f2" stop-opacity=".3"/><stop offset="1" stop-color="#1877f2" stop-opacity="0"/></linearGradient></defs><path d="${area}" fill="url(#financeGrad)"/><path d="${line}" fill="none" stroke="#1877f2" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${coords.map(q=>`<circle cx="${q[0]}" cy="${q[1]}" r="3.5" fill="#fff" stroke="#1877f2" stroke-width="2"/>`).join('')}</svg>`;}
    function renderReadout(data){const t=data.totals||{},connected=(data.systems||[]).filter(x=>x.status==='ok').length;document.getElementById('financeReadout').innerHTML=`<div style="display:grid;gap:12px"><div style="display:flex;justify-content:space-between;gap:12px;padding:12px;border-radius:12px;background:#f3f8ff"><span style="font-size:12px;color:#72809a">Collection coverage</span><strong>${connected}/${(data.systems||[]).length} systems connected</strong></div><div style="display:flex;justify-content:space-between;gap:12px;padding:12px;border-radius:12px;background:#eefbf7"><span style="font-size:12px;color:#72809a">Settlement rate</span><strong>${t.gross_amount?Math.round((t.paid_amount||0)/t.gross_amount*100):0}% of value collected</strong></div><div style="display:flex;justify-content:space-between;gap:12px;padding:12px;border-radius:12px;background:#fff7e8"><span style="font-size:12px;color:#72809a">Attention queue</span><strong>${count(t.pending_count||0)} pending records</strong></div></div>`;}
    function render(data){if(!data||!data.success)return;const t=data.totals||{};set('kpiPaid',fmt(t.paid_amount));set('kpiPaidCount',count(t.paid_count));set('kpiGross',fmt(t.gross_amount));set('kpiCount',count(t.payment_count));set('kpiPending',fmt(t.pending_amount));set('kpiPendingCount',count(t.pending_count));set('kpiCancelled',fmt(t.cancelled_amount));set('kpiCancelledCount',count(t.cancelled_count));set('kpiLatest',time(t.last_payment_at));set('financeUpdated','Updated '+new Date(data.updated_at||Date.now()).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'}));renderSystems(data.systems);renderBars('financeStatuses',data.status_summary,'status');renderBars('financeServices',data.service_summary,'service');renderTrend(data.trend);renderReadout(data);document.getElementById('financeAlert').classList.toggle('show',(data.systems||[]).some(x=>x.status!=='ok'&&x.status!=='syncing'));}
    async function refresh(){if(inFlight)return;inFlight=true;try{const res=await fetch(endpoint,{headers:{Accept:'application/json'},cache:'no-store'});if(!res.ok)throw new Error('unavailable');render(await res.json());}catch(e){document.getElementById('financeAlert').classList.add('show');set('financeUpdated','Sync unavailable · retrying');}finally{inFlight=false;}}
    render(initial);setInterval(refresh,10000);
})();
</script>
